package com.workworth.earnings.application;
import com.workworth.earnings.exception.EarningNotFoundException; import com.workworth.earnings.persistence.*; import java.time.LocalDate; import java.util.*; import org.springframework.data.domain.*; import org.springframework.stereotype.Service;
@Service public class EarningQueryService {private final WorkdayEarningRepository earnings;private final EarningCorrectionRepository corrections;public EarningQueryService(WorkdayEarningRepository e,EarningCorrectionRepository c){earnings=e;corrections=c;} public WorkdayEarning byDate(LocalDate date){return earnings.findAll().stream().filter(e->e.getLocalDate().equals(date)).findFirst().orElseThrow(()->new EarningNotFoundException("No earning exists for this workday."));}public List<WorkdayEarning> history(int page,int size){var all=earnings.findAll();all.sort(Comparator.comparing(WorkdayEarning::getLocalDate).reversed());int from=Math.min(page*size,all.size());return all.subList(from,Math.min(from+size,all.size()));}public List<EarningCorrection> corrections(LocalDate date){return corrections.findByEarningIdOrderBySequenceDesc(byDate(date).getId());}}
